  margin-bottom: 20px;
}

.cart-items {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--border);
}

.cart-item {
  display: grid;
  grid-template-columns: 1fr auto auto auto;
  align-items: center;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}

.cart-item-name {
  color: var(--text-h);
  font-size: 16px;
}

.cart-item-unit-price,
.cart-item-subtotal {
  font-family: var(--mono);
  font-size: 15px;
  text-align: right;
}

.cart-item-subtotal {
  min-width: 92px;
  color: var(--text-h);
}

.cart-stepper {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

