.cart {
  width: 560px;
  max-width: 100%;
  margin: 48px auto;
  padding: 0 20px;
  box-sizing: border-box;
  text-align: left;
}

.cart-title {
  margin-bottom: 20px;
}

.cart-items {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--border);
}

.cart-item {
  display: grid;
  grid-template-columns: 1fr auto auto auto;
  align-items: center;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}

.cart-item-name {
  color: var(--text-h);
  font-size: 16px;
}

.cart-item-unit-price,
.cart-item-subtotal {
  font-family: var(--mono);
  font-size: 15px;
  text-align: right;
}

.cart-item-subtotal {
  min-width: 92px;
  color: var(--text-h);
}

.cart-stepper {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.cart-stepper-button {
  width: 26px;
  height: 26px;
  padding: 0;
  font-size: 15px;
  line-height: 1;
  border-radius: 6px;
  color: var(--accent);
  background: var(--accent-bg);
  border: 1px solid transparent;
  cursor: pointer;
  transition: border-color 0.2s;
}

.cart-stepper-button:hover {
  border-color: var(--accent-border);
}

.cart-stepper-button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.cart-item-quantity {
  min-width: 28px;
  font-family: var(--mono);
  font-size: 15px;
  color: var(--text-h);
  text-align: center;
}

.cart-empty {
  padding: 24px 0;
  border-block: 1px solid var(--border);
}

.cart-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-top: 16px;
  color: var(--text-h);
}

.cart-total strong {
  font-family: var(--mono);
  font-size: 20px;
}

