import { expect, test } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import CartList from './CartList';

test('stepper updates quantity, subtotal, total, and removes at 0', async () => {
  const user = userEvent.setup();
  render(<CartList />);

  // 3 rows initially
  expect(screen.getAllByRole('listitem')).toHaveLength(3);
  // 18500*2 + 24000 + 4800*3 = 75400
  expect(screen.getByText('₩75,400')).toBeTruthy();

  await user.click(screen.getByLabelText('보온 텀블러 500ml 수량 늘리기'));
  expect(screen.getByText('₩99,400')).toBeTruthy();

  await user.click(screen.getByLabelText('보온 텀블러 500ml 수량 줄이기'));
  await user.click(screen.getByLabelText('보온 텀블러 500ml 수량 줄이기'));
  // row removed at 0
  expect(screen.getAllByRole('listitem')).toHaveLength(2);
  expect(screen.queryByText('보온 텀블러 500ml')).toBeNull();
  expect(screen.getByText('₩51,400')).toBeTruthy();

  // empty out the rest
  for (const label of [
    '아메리카노 원두 1kg 수량 줄이기',
    '드립 필터 100매 수량 줄이기',
  ]) {
    while (screen.queryByLabelText(label)) {
      await user.click(screen.getByLabelText(label));
    }
  }
  expect(screen.getByText('담은 항목이 없습니다.')).toBeTruthy();
  expect(screen.getByText('₩0')).toBeTruthy();
});

